// Package web 是 HTTP 层：入参校验与响应编码，业务逻辑一律下沉到 service。
package web

import (
	"encoding/json"
	"io"
	"net/http"
	"strings"

	"icewright.local/{{artifact_id}}/config"
	"icewright.local/{{artifact_id}}/domain"
	"icewright.local/{{artifact_id}}/service"
)

const (
	maxSessionIDLen = 128
	maxMessageLen   = 4000
	maxBodyBytes    = 1 << 20
)

type chatRequest struct {
	SessionID string `json:"session_id"`
	Message   string `json:"message"`
	Language  string `json:"language"`
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

func writeError(w http.ResponseWriter, detail string) {
	writeJSON(w, http.StatusBadRequest, map[string]string{"detail": detail})
}

// Handlers 聚合三条路由：GET /、GET /healthz、POST /chat。
type Handlers struct {
	chat      *service.ChatService
	sessions  *service.SessionService
	indexHTML func(w http.ResponseWriter, r *http.Request)
}

func NewHandlers(chat *service.ChatService, sessions *service.SessionService, indexHTML func(http.ResponseWriter, *http.Request)) *Handlers {
	return &Handlers{chat: chat, sessions: sessions, indexHTML: indexHTML}
}

func (h *Handlers) Chat(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		writeError(w, "仅支持 POST")
		return
	}
	raw, err := io.ReadAll(io.LimitReader(r.Body, maxBodyBytes))
	if err != nil {
		writeError(w, "请求体读取失败")
		return
	}
	var req chatRequest
	if err := json.Unmarshal(raw, &req); err != nil {
		writeError(w, "请求体不是合法 JSON（字段：session_id/message/language）")
		return
	}
	if req.SessionID == "" || len([]rune(req.SessionID)) > maxSessionIDLen {
		writeError(w, "session_id 必须非空且不超过 128 字符")
		return
	}
	if req.Message == "" || len([]rune(req.Message)) > maxMessageLen {
		writeError(w, "message 必须非空且不超过 4000 字符")
		return
	}
	lang := strings.ToLower(strings.TrimSpace(req.Language))
	if lang == "" {
		lang = domain.DefaultLanguage
	}
	if lang != "zh" && lang != "en" {
		writeError(w, "language 仅支持 zh/en")
		return
	}
	writeJSON(w, http.StatusOK, h.chat.Answer(req.SessionID, req.Message, lang))
}

func (h *Handlers) Healthz(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, map[string]any{
		"project":   config.Project,
		"pack_ref":  config.PackRef,
		"redis":     h.sessions.RedisPing(),
		"languages": domain.Languages(),
	})
}

func (h *Handlers) Home(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, "仅支持 GET")
		return
	}
	h.indexHTML(w, r)
}
